      const store=stores.find(s=>s.id===storeId),id='BW'+stamp.replace(/[- :]/g,'').slice(2)+'-'+String(operations.length+1).padStart(2,'0');
      const op={id,store,stamp,mode,boardType,backendConfig:snapshotBackendConfig(backendConfig),operator:store.person,staff:store.staff,role:'店长',source:'移动端',records:[],selectedCount:days.length};
      days.forEach((date,index)=>{const key=storeId+'|'+date,before=latest.has(key)?clone(latest.get(key)):null,after=change(before?clone(before):null,date,index);if(!validateSnapshot(after))throw Error('示例床位配置不合法：'+key);const fields=fieldsFor(before,after),changed=fields.filter(f=>f.changed);if(!changed.length)return;const record={id:id+'|'+date,op,date,before,after,fields,changes:changed,explicit:changed.filter(f=>!f.derived),initial:!before};op.records.push(record);latest.set(key,clone(after));});
      if(op.records.length)operations.push(op);
