    addOperation('HZ001','2026-10-10 10:20:18','batch',dateRange('2026-10-14',7),()=>snapshot(8,10,2),'old');
    addOperation('SZ001','2026-10-11 08:45:09','batch',dateRange('2026-10-14',7),()=>snapshot(8,10,2),'old');
    addOperation('SH001','2026-10-01 09:10:32','batch',dateRange('2026-10-14',15),()=>snapshot(8,12,3),'old');
    addOperation('SH002','2026-10-11 09:36:41','batch',dateRange('2026-10-14',15),()=>{const s=snapshot(8,10,2);s.new.types.yimei=3;return s;},'old');
    addOperation('SH003','2026-10-12 08:55:26','batch',dateRange('2026-10-14',10),()=>snapshot(8,10,2),'old');
    addOperation('SH001','2026-10-12 09:20:18','batch',['2026-10-17','2026-10-18'],b=>{b.new.total=10;return b;},'old');
    addOperation('NJ001','2026-10-12 09:40:17','batch',dateRange('2026-10-14',8),()=>snapshot(6,8,0,false),'old');
