    addOperation('SH001','2026-10-12 15:10:46','batch',['2026-10-16','2026-10-17','2026-10-18'],()=>{const s=snapshot(9,12,3);s.new.types.shengmei=3;return s;},'new');
    addOperation('SH002','2026-10-13 08:20:06','batch',dateRange('2026-10-17',7),()=>{const s=snapshot(10,12,2);s.new.types.shengmei=4;return s;},'new');
    addOperation('SH002','2026-10-13 08:45:12','single',['2026-10-15'],b=>{b.new.types.yimei=2;b.new.types.shengmei=3;return b;},'new');
    addOperation('SZ001','2026-10-13 09:06:35','single',['2026-10-16'],b=>{b.new.total=6;b.new.types.shengmei=1;return b;},'new');
    addOperation('SH001','2026-10-13 09:42:08','single',['2026-10-15'],b=>{b.shared.x10=2;return b;},'new');
    addOperation('HZ001','2026-10-13 10:08:22','single',['2026-10-17'],b=>{b.new.total+=2;b.new.types.shengmei+=2;return b;},'new');
    addInterval('NJ001','2026-10-13 10:22:31',60,90,'new');
