function copyBed(id){let r=clone(managementContext.data.bedRules.find(x=>x.id===id));r.id=uid('bed');r.name+='（副本）';r.status=false;r.updated=stamp();managementContext.data.bedRules.push(r);history('bedRules',r.id,'复制床位规则',null,r);save('已复制');refresh()}
