function bedRecord(store,date){return allBedOps().flatMap(op=>op.records.map(r=>({...r,op}))).filter(r=>r.op.store.id===store&&r.date===date&&r.op.mode!=='interval'&&r.op.kind!=='store-seats').sort((a,b)=>b.op.stamp.localeCompare(a.op.stamp))[0]}
