function logsPage(){let f=q['bed-logs']||{},stores=seatLogStores().filter(x=>matches(x,f.q));return searchBar('bed-logs',[['date','排客日期（生效日期）',null,'date']])+list('床位变更记录',['序号','门店','新客床位（总数 / 通用）','老客床位（总数 / 通用）','最近操作','操作'],stores.map((s,i)=>{let entries=logEntries(s.id),rec=f.date?bedRecord(s.id,f.date):null;return [i+1,e(s.name)+'<div class="muted">'+e(s.id+' · '+s.area)+'</div>',rec?rec.after.new.total+' / '+UBLog.general(rec.after,'new'):(f.date?'—':'请选择排客日期'),rec?rec.after.old.total+' / '+UBLog.general(rec.after,'old'):(f.date?'—':'请选择排客日期'),entries[0]?e(entries[0].op.operator)+'<div class="muted">'+e(entries[0].op.stamp)+'</div>':'暂无记录',actions(link('查看日志',`UB.openLogs('${s.id}')`),link('导出',`UB.exportLogs('${s.id}')`))]}))}
