function seatRows(){let f=seatFilter;return seatStores.filter(s=>matches(s.name,f.q)&&(!f.district?.length||f.district.includes(s.district))&&(!f.area?.length||f.area.includes(s.area))&&(!f.store?.length||f.store.includes(s.id)))}
