function seatFilterControl(key,label){let values=seatDraft[key]||[],text=key==='store'?values.map(id=>seatStores.find(s=>s.id===id)?.name).join('、'):values.join('、');return `<button type="button" class="btn seat-filter-picker" aria-label="${label}" title="${e(text||label)}" onclick="UB.seatPickFilter('${key}')"><span>${e(text||label)}</span>${icon('down')}</button>`}
